#include <iostream>
#include <memory>
#include <optional>
#include <print>
#include <string>
#include <utility>

int destroyed = 0;

struct Node {
    int value;
    std::shared_ptr<Node> next;
    std::weak_ptr<Node> prev;
    explicit Node(int v) : value(v) {}
    ~Node() {
        ++destroyed;
    }
};

class List {
public:
    List() = default;
    List(const List &) = delete;
    List &operator=(const List &) = delete;
    ~List() {
        while (head_) {
            head_ = std::move(head_->next);
        }
    }

    void push_back(int x) {
        auto node = std::make_shared<Node>(x);
        if (auto tail = tail_.lock()) {
            node->prev = tail;
            tail->next = node;
        } else {
            head_ = node;
        }
        tail_ = node;
    }

    void push_front(int x) {
        auto node = std::make_shared<Node>(x);
        if (head_) {
            head_->prev = node;
            node->next = std::move(head_);
        } else {
            tail_ = node;
        }
        head_ = std::move(node);
    }

    std::optional<int> pop_front() {
        if (!head_) {
            return std::nullopt;
        }
        const int v = head_->value;
        head_ = std::move(head_->next);
        if (head_) {
            head_->prev.reset();
        }
        return v;
    }

    std::optional<int> pop_back() {
        auto tail = tail_.lock();
        if (!tail) {
            return std::nullopt;
        }
        const int v = tail->value;
        if (auto prev = tail->prev.lock()) {
            tail_ = prev;
            prev->next.reset();
        } else {
            head_.reset();
        }
        return v;
    }

    void forward() const {
        std::string s;
        for (const Node *n = head_.get(); n; n = n->next.get()) {
            s += (s.empty() ? "" : " ") + std::to_string(n->value);
        }
        std::println("вперёд: {}", s.empty() ? "—" : s);
    }

    void backward() const {
        std::string s;
        for (auto n = tail_.lock(); n; n = n->prev.lock()) {
            s += (s.empty() ? "" : " ") + std::to_string(n->value);
        }
        std::println("назад: {}", s.empty() ? "—" : s);
    }

private:
    std::shared_ptr<Node> head_;
    std::weak_ptr<Node> tail_;
};

void show_value(std::optional<int> v) {
    if (v) {
        std::println("{}", *v);
    } else {
        std::println("пусто");
    }
}

int main() {
    {
        List list;
        std::string command;
        while (std::cin >> command) {
            if (command == "push_back" || command == "push_front") {
                int x;
                std::cin >> x;
                if (command == "push_back") {
                    list.push_back(x);
                } else {
                    list.push_front(x);
                }
            } else if (command == "pop_back") {
                show_value(list.pop_back());
            } else if (command == "pop_front") {
                show_value(list.pop_front());
            } else if (command == "forward") {
                list.forward();
            } else if (command == "backward") {
                list.backward();
            } else {
                std::println("удалено узлов {}", destroyed);
            }
        }
    }
    std::println("удалено узлов {}", destroyed);
    return 0;
}

